<!DOCTYPE html>
<html lang="id">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <meta name="theme-color" content="#070b14">
    <title>Project Showcase · Tazaka</title>
    <link rel="icon" type="image/png" href="https://tazaka.co.id/assets/logo-tazaka-PPqkEZXu.png">
    <style>
        *{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden}body{font-family:Inter,ui-sans-serif,system-ui,sans-serif;background:#050913;color:#f8fafc}.idle{position:relative;width:100%;height:100%;display:flex;align-items:center;justify-content:center;overflow:hidden;background:radial-gradient(circle at 78% 20%,rgba(56,189,248,.13),transparent 32%),radial-gradient(circle at 15% 85%,rgba(99,102,241,.1),transparent 30%),#050913}.ambient{position:absolute;inset:0;pointer-events:none;background:linear-gradient(115deg,transparent 0 46%,rgba(255,255,255,.025) 46.1%,transparent 46.4%)}.brand{position:absolute;top:30px;left:36px;display:flex;align-items:center;gap:12px;z-index:4}.brand img{width:46px;height:46px;object-fit:contain;background:#fff;border-radius:12px;padding:5px}.brand small{display:block;font-size:9px;letter-spacing:.22em;text-transform:uppercase;color:#7dd3fc;font-weight:800}.brand strong{display:block;margin-top:3px;font-size:15px;letter-spacing:.01em}.counter{position:absolute;top:36px;right:40px;z-index:4;text-align:right}.counter-label{font-size:9px;letter-spacing:.18em;text-transform:uppercase;color:#64748b}.counter-value{font-size:13px;font-weight:800;color:#cbd5e1;margin-top:4px}.stage{position:relative;width:min(1180px,88vw);height:min(690px,82vh);display:flex;align-items:center;justify-content:center}.project-card{position:absolute;width:min(1000px,100%);height:min(590px,76vh);padding:54px 62px;border:1px solid rgba(148,163,184,.22);border-radius:34px;background:linear-gradient(135deg,rgba(24,39,63,.98),rgba(8,16,30,.99) 58%,rgba(15,28,49,.98));box-shadow:0 35px 100px rgba(0,0,0,.48),inset 0 1px 0 rgba(255,255,255,.04);display:grid;grid-template-columns:1.45fr .7fr;gap:45px;overflow:hidden;opacity:0;transform:translateX(70px) scale(.98);transition:opacity .7s ease,transform .7s cubic-bezier(.22,.61,.36,1)}.project-card::before{content:"";position:absolute;width:460px;height:460px;right:-190px;top:-210px;border-radius:50%;background:radial-gradient(circle,rgba(56,189,248,.22),transparent 67%);pointer-events:none}.project-card::after{content:"";position:absolute;width:560px;height:560px;right:-300px;bottom:-390px;border:1px solid rgba(255,255,255,.07);border-radius:50%;box-shadow:0 0 0 30px rgba(255,255,255,.014),0 0 0 60px rgba(255,255,255,.01);pointer-events:none}.project-card.active{opacity:1;transform:translateX(0) scale(1)}.project-card.exit{opacity:0;transform:translateX(-70px) scale(.98)}.left,.right{position:relative;z-index:1}.eyebrow{font-size:11px;letter-spacing:.24em;text-transform:uppercase;color:#7dd3fc;font-weight:850}.name{font-size:clamp(38px,5vw,70px);line-height:1.02;letter-spacing:-.045em;font-weight:900;margin:14px 0 10px;max-width:700px}.client{font-size:18px;color:#94a3b8}.type{display:inline-flex;margin-top:28px;padding:8px 13px;border:1px solid rgba(125,211,252,.24);border-radius:999px;background:rgba(15,23,42,.7);font-size:10px;color:#bae6fd;font-weight:800;letter-spacing:.1em;text-transform:uppercase}.progress-block{margin-top:54px}.progress-head{display:flex;align-items:flex-end;justify-content:space-between;gap:20px;margin-bottom:12px}.progress-label{font-size:10px;letter-spacing:.17em;text-transform:uppercase;color:#64748b}.percent{font-size:48px;line-height:1;font-weight:900;transition:color .45s ease,transform .45s ease}.percent.bump{transform:scale(1.08)}.bar{height:10px;border-radius:99px;background:#162236;overflow:hidden}.bar span{display:block;height:100%;width:0;border-radius:99px;background:#38bdf8;box-shadow:0 0 16px rgba(56,189,248,.22);transition:width 1s cubic-bezier(.22,.61,.36,1),background .45s ease,box-shadow .45s ease}.progress-low .percent{color:#fb7185}.progress-low .bar span{background:#fb7185;box-shadow:0 0 16px rgba(251,113,133,.25)}.progress-medium .percent{color:#fbbf24}.progress-medium .bar span{background:#fbbf24;box-shadow:0 0 16px rgba(251,191,36,.25)}.progress-high .percent{color:#38bdf8}.progress-high .bar span{background:#38bdf8;box-shadow:0 0 16px rgba(56,189,248,.25)}.progress-complete .percent{color:#34d399}.progress-complete .bar span{background:#34d399;box-shadow:0 0 16px rgba(52,211,153,.25)}.details{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:34px}.detail{padding:15px 16px;border:1px solid rgba(148,163,184,.13);border-radius:15px;background:rgba(15,23,42,.45)}.detail-label{font-size:8px;letter-spacing:.15em;text-transform:uppercase;color:#64748b}.detail-value{margin-top:5px;font-size:13px;color:#e2e8f0;font-weight:750}.right{display:flex;flex-direction:column;justify-content:center;align-items:center;text-align:center}.project-number{font-size:clamp(80px,11vw,150px);line-height:.8;font-weight:950;letter-spacing:-.08em;color:rgba(255,255,255,.055)}.remaining{margin-top:28px}.remaining strong{display:block;font-size:clamp(42px,5vw,68px);line-height:1;font-weight:900}.remaining span{display:block;margin-top:8px;font-size:10px;letter-spacing:.2em;text-transform:uppercase;color:#64748b}.description{margin-top:32px;color:#cbd5e1;font-size:12px;max-width:280px;line-height:1.65;text-align:left;max-height:155px;overflow:hidden}.description p{margin:0 0 10px}.description p:last-child{margin-bottom:0}.description strong{color:#f8fafc}.description ul,.description ol{margin:7px 0 0;padding-left:19px}.description li{margin:3px 0}.empty{font-size:20px;color:#94a3b8;text-align:center}.controls{position:absolute;left:36px;bottom:32px;z-index:5;display:flex;gap:8px;align-items:center}.floating{border:1px solid rgba(148,163,184,.22);background:rgba(7,11,20,.72);backdrop-filter:blur(12px);color:#cbd5e1;border-radius:999px;padding:11px 15px;font-size:11px;font-weight:750;cursor:pointer;box-shadow:0 10px 30px rgba(0,0,0,.25);transition:.2s}.floating:hover{background:#111827;color:#fff;border-color:rgba(125,211,252,.4)}.dots{position:absolute;left:50%;bottom:42px;transform:translateX(-50%);z-index:5;display:flex;gap:7px}.dot{width:7px;height:7px;border-radius:50%;background:#334155;transition:.3s}.dot.active{width:22px;border-radius:99px;background:#38bdf8}.hint{position:absolute;right:36px;bottom:36px;color:#475569;font-size:9px;letter-spacing:.08em;text-transform:uppercase}@media(max-width:800px){.brand{top:18px;left:18px}.counter{top:22px;right:18px}.stage{width:92vw;height:78vh}.project-card{height:auto;min-height:610px;padding:34px 28px;grid-template-columns:1fr;gap:10px;border-radius:26px}.name{font-size:40px}.client{font-size:15px}.progress-block{margin-top:34px}.right{display:none}.details{margin-top:25px}.controls{left:18px;bottom:18px}.dots{bottom:28px}.hint{display:none}}
    </style>
</head>
<body>
<div class="idle">
    <div class="ambient"></div>
    <div class="brand"><img src="https://tazaka.co.id/assets/logo-tazaka-PPqkEZXu.png" alt="Tazaka"><div><small>Tazaka Elektrik Mandiri</small><strong>Project Showcase</strong></div></div>
    <div class="counter"><div class="counter-label">Now Showing</div><div class="counter-value" id="counter">0 / 0</div></div>
    <main class="stage" id="stage"><div class="empty">Memuat project...</div></main>
    <div class="dots" id="dots"></div>
    <div class="controls"><button class="floating" type="button" id="backBtn">← Dashboard</button><button class="floating" type="button" id="pauseBtn">Ⅱ Pause</button></div>
    <div class="hint">Auto rotation · 15 seconds</div>
</div>
<script src="https://cdn.jsdelivr.net/npm/pusher-js@8.4.0/dist/web/pusher.min.js"></script>
<script>
const dataUrl=@json(route('monitor.data'));
const projectsUrl=@json(route('monitor'));
const rotationMs=15000;
const refreshMs=3000;
let projects=[];let current=0;let timer=null;let paused=false;let transitionTimer=null;
const stage=document.getElementById('stage');const dots=document.getElementById('dots');const counter=document.getElementById('counter');
function esc(v){return String(v??'').replace(/[&<>'\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function richText(v){return String(v??'').trim()}
function typeLabel(v){return{tazaka_order:'Tazaka Order',subcontract:'Subcontract',external:'External'}[v]??v??'-'}
function date(v){if(!v)return '-';const d=new Date(String(v).slice(0,10)+'T00:00:00');return Number.isNaN(d.getTime())?String(v):new Intl.DateTimeFormat('id-ID',{day:'2-digit',month:'short',year:'numeric'}).format(d)}
function daysLeft(v,progress){if(!v||Number(progress)>=100)return Number(progress)>=100?'Completed':'-';const target=new Date(String(v).slice(0,10)+'T23:59:59');if(Number.isNaN(target.getTime()))return '-';return Math.ceil((target-new Date())/86400000)}
function progressClass(progress){if(progress>=100)return'progress-complete';if(progress<=30)return'progress-low';if(progress<=70)return'progress-medium';return'progress-high'}
function card(p,index){const progress=Math.max(0,Math.min(100,Number(p.progress||0)));const left=daysLeft(p.target_completion_date,progress);return `<article class="project-card active"><div class="left"><div class="eyebrow">Project ${String(index+1).padStart(2,'0')}</div><div class="name">${esc(p.name)}</div><div class="client">${esc(p.client)}</div><div class="type">${esc(typeLabel(p.project_type))}</div><div class="progress-block ${progressClass(progress)}"><div class="progress-head"><span class="progress-label">Overall Progress</span><span class="percent">${progress}%</span></div><div class="bar"><span style="width:${progress}%"></span></div></div><div class="details"><div class="detail"><div class="detail-label">Target Completion</div><div class="detail-value">${esc(date(p.target_completion_date))}</div></div><div class="detail"><div class="detail-label">Project Month</div><div class="detail-value">${esc(p.project_month?new Intl.DateTimeFormat('id-ID',{month:'long',year:'numeric'}).format(new Date(String(p.project_month).slice(0,7)+'-01T00:00:00')):'-')}</div></div><div class="detail"><div class="detail-label">Location</div><div class="detail-value">${esc(p.location||'-')}</div></div><div class="detail"><div class="detail-label">Status</div><div class="detail-value">${progress>=100?'Completed':(left!=='-'&&Number(left)<0?'Delayed':'Running')}</div></div></div></div><div class="right"><div class="project-number">${String(index+1).padStart(2,'0')}</div><div class="remaining"><strong>${typeof left==='number'?Math.abs(left):left}</strong><span>${typeof left==='number'?(left<0?'Days Overdue':'Days Remaining'):''}</span></div>${richText(p.description)?`<div class="description">${richText(p.description)}</div>`:''}</div></article>`}
function renderDots(){dots.innerHTML=projects.map((_,i)=>`<span class="dot ${i===current?'active':''}"></span>`).join('')}
function animateNumber(el,from,to,duration=900){if(from===to){el.textContent=`${to}%`;return}const start=performance.now();function frame(now){const t=Math.min(1,(now-start)/duration);const eased=1-Math.pow(1-t,3);el.textContent=`${Math.round(from+(to-from)*eased)}%`;if(t<1)requestAnimationFrame(frame)}requestAnimationFrame(frame)}
function updateCurrentProgress(p){const old=stage.querySelector('.project-card');if(!old)return false;const block=old.querySelector('.progress-block');const percentEl=old.querySelector('.percent');const bar=old.querySelector('.bar span');if(!block||!percentEl||!bar)return false;const next=Math.max(0,Math.min(100,Number(p.progress||0)));const previous=Math.max(0,Math.min(100,Number(percentEl.textContent.replace('%',''))||0));if(previous===next)return true;block.classList.remove('progress-low','progress-medium','progress-high','progress-complete');block.classList.add(progressClass(next));percentEl.classList.add('bump');animateNumber(percentEl,previous,next,900);bar.style.width=`${next}%`;setTimeout(()=>percentEl.classList.remove('bump'),450);return true}
function show(index,animate=true){if(!projects.length){stage.innerHTML='<div class="empty">Belum ada project aktif.</div>';counter.textContent='0 / 0';dots.innerHTML='';return}current=(index+projects.length)%projects.length;const old=stage.querySelector('.project-card');const html=card(projects[current],current);if(old&&animate){old.classList.remove('active');old.classList.add('exit');clearTimeout(transitionTimer);transitionTimer=setTimeout(()=>{stage.innerHTML=html},650)}else{stage.innerHTML=html}counter.textContent=`${current+1} / ${projects.length}`;renderDots()}
function restartTimer(){clearInterval(timer);if(!paused&&projects.length>1)timer=setInterval(()=>show(current+1),rotationMs)}
async function loadProjects(keepCurrent=true){try{const res=await fetch(dataUrl,{headers:{Accept:'application/json'},cache:'no-store'});if(!res.ok)throw new Error('HTTP '+res.status);const json=await res.json();const previousId=projects[current]?.id;const oldIds=projects.map(p=>p.id);const nextProjects=Array.isArray(json.projects)?json.projects:[];projects=nextProjects;let next=projects.findIndex(p=>p.id===previousId);if(!keepCurrent||next<0)next=0;const structureChanged=oldIds.length!==projects.length||oldIds.some((id,i)=>id!==projects[i]?.id);if(previousId&&next>=0&&projects[next]?.id===previousId&&!structureChanged){current=next;updateCurrentProgress(projects[current]);counter.textContent=`${current+1} / ${projects.length}`;renderDots();return}show(next,false);if(structureChanged)restartTimer();}catch(e){console.error('Project showcase:',e)}}
document.getElementById('backBtn').addEventListener('click',()=>{window.location.href=projectsUrl});
document.getElementById('pauseBtn').addEventListener('click',()=>{paused=!paused;document.getElementById('pauseBtn').textContent=paused?'▶ Play':'Ⅱ Pause';restartTimer()});
loadProjects(false);setInterval(()=>loadProjects(true),refreshMs);
try{const host=window.location.hostname;const port=@json((int) env('REVERB_PORT',8080));const key=@json(env('REVERB_APP_KEY'));if(window.Pusher&&key){const pusher=new Pusher(key,{wsHost:host,wsPort:port,wssPort:port,forceTLS:false,enabledTransports:['ws','wss']});const channel=pusher.subscribe('monitor');channel.bind('project.updated',()=>loadProjects(true));}}catch(e){console.warn('Realtime unavailable:',e)}
</script>
</body>
</html>
